; The scan of the cave map
; $7da3-$7e3d

; Stops the amoeba growth when no amoeba cell had room now but one had room in the scan before. Keeps the amoeba count.
update_amoeba_room
        lda amoeba_room_found
        bne update_amoeba_counts
        lda amoeba_room_last
        beq update_amoeba_counts
; not executed $7dab-$7dae
        lda #$00                        ; The amoeba becomes diamonds.
        sta amoeba_growing
update_amoeba_counts
        lda amoeba_room_found
        sta amoeba_room_last
        lda #$00
        sta amoeba_room_found
        lda amoeba_count
        sta amoeba_count_last
        lda #$00
        sta amoeba_count
        rts
; Reads fire. When no Rockford is in the cave for 16 scans, the clock ran a second and fire is pressed, it ends the play.
check_restart_fire
        jsr read_fire_current_player
        lda rockford_absent
        cmp #$10
        bne check_restart_done
        lda fire_button
        bne check_restart_done
        lda seconds_elapsed
        beq check_restart_done
        lda #$02
        sta cave_end_state
check_restart_done
        rts
; Scans the cave once. Each cell runs the handler of its element or gets the settled code. Then it reads the game keys.
scan_cave
        lda #$16                        ; 22 rows, or 15 rows for an intermission.
        sta view_row_ptrs
        lda cave_number
        cmp #$11
        bcc scan_cave_start
        lda #$0f
        sta view_row_ptrs
scan_cave_start
        lda #$01
        sta scan_row
        jsr cell_ptr_to_row_start
        lda #$10                        ; Counts the scans without Rockford, at most 16. The Rockford handler sets it to 0.
        cmp rockford_absent
        beq scan_cave_checks
        inc rockford_absent
scan_cave_checks
        jsr check_restart_fire
        jsr update_amoeba_room
scan_cave_row
        lda #$00
        sta scan_col
scan_cell
        ldy #$29
        lda (cell_ptr),y
        asl
        tax
        lda element_handler_hi,x        ; High byte of the handler of the element. Zero: no handler.
        beq scan_cell_settle
        sta handler_vector_hi
        lda element_handler_lo,x
        sta handler_vector
        jmp (handler_vector)            ; The handler returns with jmp scan_cell_settle.
scan_cell_settle
        ldy #$00                        ; Sets the settled code of the element, when the table gives one.
        lda (cell_ptr),y
        tax
        lda cell_scan_reset,x
        beq scan_next_cell
        sta (cell_ptr),y
scan_next_cell
        inc cell_ptr
        bne scan_next_column
        inc cell_ptr_hi
scan_next_column
        inc scan_col
        lda scan_col
        cmp #$28
        bne scan_cell
        jsr scan_row_delay
        inc scan_row
        lda scan_row
        cmp view_row_ptrs
        bne scan_cave_row
        jsr check_game_keys
        rts
